chunks:
import { transformersEmbedder } from "@sweberdev/cosine"; import { buildDirectory } from "@sweberdev/cosine/node";
await buildDirectory("docs", "public/cosine", { baseUrl: "/docs", embedder: transformersEmbedder({ model: "english" }), exclude: ["drafts/"], });
buildIndex(documents, options) from @sweberdev/cosine takes documents from anywhere (a CMS, a database) and also runs in the browser.

Copy the model files (config.json, tokenizer.json, tokenizerconfig.json, onnx/modelquantized.onnx) from the model page to e.g. public/models/Xenova/all-MiniLM-L6-v2/, then point transformers.js there:
import { Cosine, loadIndex, transformersEmbedder } from "@sweberdev/cosine";
const embedder = transformersEmbedder({ model: "english", load: async () => { const transformers = await import("@huggingface/transformers"); transformers.env.allowRemoteModels = false; transformers.env.localModelPath = "/models/"; return transformers; }, }); const cosine = await loadIndex("/cosine/cosine-index.json", { embedder }); document.querySelector("cosine-search").cosine = cosine;
The ONNX runtime itself (WebAssembly) is loaded from a CDN by transformers.js; set transformers.env.backends.onnx.wasm.wasmPaths to serve it yourself as well.

import { CosineSearch } from "@sweberdev/cosine-react"; import { useRouter } from "next/navigation";
export function DocsSearch() { const router = useRouter(); return ( <CosineSearch index="/cosine/cosine-index.json" lang="de" shortcut="mod+k" onSelect={(result) => { router.push(result.chunk.url); return false; // Cosine does not navigate itself }} /> ); }
CosineSearch renders the web component, so attributes, styling and accessibility are the same. scope takes a string or an array, e.g. scope={["/docs/api", "/docs/guides"]}, and so does index, to search several indexes as one: index={["/docs/cosine-index.json", "/blog/cosine-index.json"]}. facets shows the filter buttons per section.

import { useCosine, useCosineSearch } from "@sweberdev/cosine-react"; import { useState } from "react";
export function Search() { const { cosine, status } = useCosine("/cosine/cosine-index.json"); const [query, setQuery] = useState(""); const { results } = useCosineSearch(cosine, query, { limit: 5, groupByPage: true, scope: "/docs" });
return ( <> <input value={query} onChange={(e) => setQuery(e.target.value)} onFocus={() => cosine?.warmup()} /> {status === "loading-model" && <p>Loading smart search…</p>} <ul> {results.map((r) => ( <li key={r.chunk.id}> <a href={r.chunk.url}>{[r.chunk.title, ...r.chunk.headings].join(" › ")}</a> <p>{r.snippet}</p> </li> ))} </ul> </> ); }
useCosineSearch returns keyword results on every keystroke and switches to the hybrid ranking as soon as the model is ready.

With a static export (output: "export"), index the exported HTML after the build:
{ "scripts": { "build": "next build && cosine build out --out out/cosine" } }
"use client";
import { CosineSearch } from "@sweberdev/cosine-react"; import { useRouter } from "next/navigation";
export function Search() { const router = useRouter(); return ( <CosineSearch index="/cosine/cosine-index.json" onSelect={(result) => { router.push(result.chunk.url); return false; }} /> ); }
Install @sweberdev/cosine-react as well, see React. For sites that are not exported, cosine-next (Cosine Pro) reads the prerendered pages in .next and caches the index between builds.

Set cleanUrls: true in the VitePress config, so the page URLs match.
import { cosineBuildEnd } from "@sweberdev/cosine/vitepress";
export default defineConfig({ cleanUrls: true, buildEnd: cosineBuildEnd() });
cosineBuildEnd indexes the built HTML in .vitepress/dist/cosine/ and uses the site's base. To index the Markdown sources instead, run cosine build docs --out docs/public/cosine before vitepress build docs.
import DefaultTheme from "vitepress/theme"; import { h } from "vue";
export default { extends: DefaultTheme, Layout() { return h(DefaultTheme.Layout, null, { "nav-bar-content-before": () => h("cosine-search", { index: "/cosine/cosine-index.json" }), }); }, async enhanceApp() { if (!import.meta.env.SSR) await import("@sweberdev/cosine/element"); }, };
If the site has a base, build with --base-url /base/ and use /base/cosine/cosine-index.json as the index.

With adapter-static:
{ "scripts": { "build": "vite build && cosine build build --out build/cosine" } }
<script> import { onMount } from "svelte";
onMount(() => import("@sweberdev/cosine/element")); </script>
<cosine-search index="/cosine/cosine-index.json"></cosine-search> <slot />

Build the index from your Markdown before the Vite build and tell Vue that cosine-search is a custom element:
{ "scripts": { "prebuild": "cosine build content --out public/cosine --base-url /docs" } }
import vue from "@vitejs/plugin-vue"; import { defineConfig } from "vite";
export default defineConfig({ plugins: [ vue({ template: { compilerOptions: { isCustomElement: (tag) => tag === "cosine-search" } } }), ], });
<script setup lang="ts"> import "@sweberdev/cosine/element";
function onSelect(event: CustomEvent) { event.preventDefault(); // handle navigation with your router console.log(event.detail.chunk.url); } </script>
<template> <cosine-search index="/cosine/cosine-index.json" @cosine-select="onSelect" /> </template>

Custom properties:
cosine-search { --cosine-accent: #d4380d; --cosine-bg: #fff; --cosine-text: #111; --cosine-muted: #555; --cosine-border: #ddd; --cosine-radius: 6px; --cosine-max-height: 70vh; --cosine-z: 100; }
For more control, style the parts: ::part(input), ::part(results), ::part(result), ::part(result-title), ::part(result-snippet), ::part(status), ::part(shortcut).

import { findAnswer, renderAnswer } from "@weber-development/cosine-answers";
const answer = findAnswer(query, results); // results from cosine.search(query) if (answer) target.innerHTML = renderAnswer(answer);
findAnswer returns { text, url, title, heading, confidence, matched } or null. Options: maxLength (280), minConfidence (0.5) and labels: { readMore }.

import { trackSearches } from "@weber-development/cosine-insights";
trackSearches(document.querySelector("cosine-search")!, { endpoint: "/api/search-insights" });
A search counts once typing has paused (1.5 s), not on every keystroke. Opening a result sends the query, the URL and its rank. Options: settleMs, sampleRate (record only a share of visitors), send (use your own analytics instead).

The handler is a plain Request → Response function:
import { createInsightsHandler } from "@weber-development/cosine-insights"; import { fileStore } from "@weber-development/cosine-insights/node";
export const POST = createInsightsHandler({ store: fileStore("data/searches.ndjson") });
It accepts same-origin requests only (set origins for others), validates every event and adds a timestamp. Implement InsightsStore (append(event)) to write to a database, KV store or log service instead of a file.

@weber-development/cosine-migrate converts the records and synonyms you export from Algolia into a Cosine index. The search then runs in the browser, without an account, a server or an API key.
npm i -D @weber-development/cosine-migrate npx cosine-migrate algolia --records records.json --synonyms synonyms.json --out public/cosine
<cosine-search index="/cosine/cosine-index.json"></cosine-search>

import { migrateFromAlgolia } from "@weber-development/cosine-migrate";
const result = await migrateFromAlgolia({ records: "records.json", synonyms: "synonyms.json", out: "public/cosine", }); console.log(result.pages, result.records, result.synonyms);
records and synonyms accept a file path or the parsed array.

@weber-development/cosine-next builds the search index from the finished HTML of your Next.js site. Run it after next build:
{ "scripts": { "build": "next build && cosine-next --base-path /docs" } }
import "@sweberdev/cosine/element";
export function Search() { return <cosine-search index="/cosine/cosine-index.json" />; }

Option | Default |
--source | out, else .next/server/app | Folder with the HTML, repeatable --out | public/cosine | Output directory --base-path | / | basePath of the site --model | english | english, multilingual or a Hugging Face model id --lexical-only | | No embeddings, keyword search only --exclude | | Skip pages whose path starts with this, repeatable --cache-dir | .next/cache/cosine | Where the last index is kept --no-cache | | Embed everything every time --config | | JSON file with more options, e.g. { "synonyms": [["login", "sign-in"]], "boost": { "/docs/api": 1.5 } }
From code: buildNextIndex({ baseUrl: "/docs", exclude: ["blog/"] }).

Cosine Pro adds what you need once search runs on more than one site: the index builds itself, and you see what people look for and do not find.
Package | What it does
@weber-development/cosine-vite | Builds the index in every Vite build (Astro, VitePress, SvelteKit, Nuxt), serves it in dev, rebuilds on change and re-embeds only the sections that changed @weber-development/cosine-next | Builds the index from the pages next build has prerendered and keeps the last index in .next/cache, so CI rebuilds embed only what changed @weber-development/cosine-migrate | Turns an Algolia DocSearch export and its synonyms into a Cosine index @weber-development/cosine-insights | Records searches without tracking people and reports queries without results, results nobody opened, the most searched topics and how they change from period to period @weber-development/cosine-answers | Quotes the sentence that answers the question above the results, with a link to the page, without an LLM @weber-development/cosine-quality | Golden queries: write down which page must answer which search and let CI fail when a change makes search worse

