interface PageResult { url: string; title: string | undefined; testedAt: string; findings: Finding[]; passedRules: number; incomplete: Finding[]; // needs manual review fixed?: { rule: string; help: string; target: string; before?: string; after?: string }[]; // with --compare-with }
interface Finding { rule: string; // axe-core rule id, e.g. "image-alt" impact: "minor" | "moderate" | "serious" | "critical"; help: string; helpUrl: string; criteria: { id: string; level?: "A" | "AA" | "AAA"; en301549: string }[]; bestPractice: boolean; nodes: { target: string; html: string; summary: string; screenshot?: string }[]; }
interface ResultsFile { version: 1; project?: string; createdAt: string; pages: PageResult[]; }

surjection init writes the config with a $schema line. Editors such as VS Code then complete field names, show the descriptions and flag typos or invalid steps while you type. For an existing file add:
{ "$schema": "https://unpkg.com/@sweberdev/surjection/surjection.config.schema.json" }
The schema ships with the package as surjection.config.schema.json.
